package com.staging.sg.fraud.gateway.api;
import com.staging.sg.fraud.gateway.api.IsoFraudApi.*;import com.staging.sg.fraud.gateway.service.*;import jakarta.validation.Valid;import org.springframework.http.HttpHeaders;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/fraud-gateway/v1") public class IsoFraudController{private final Iso8583FraudMapper mapper;private final FraudPlatformClient platform;private final GatewayEvaluationService evaluation;private final FraudLabScenarioService lab;public IsoFraudController(Iso8583FraudMapper m,FraudPlatformClient p,GatewayEvaluationService evaluation,FraudLabScenarioService lab){mapper=m;platform=p;this.evaluation=evaluation;this.lab=lab;}
 @GetMapping("/health")public Health health(){return new Health("UP","GATEWAY_REQUIRED");}
 @PostMapping("/iso8583/evaluate")public IsoMessageResponse evaluate(@RequestHeader(HttpHeaders.AUTHORIZATION)String authorization,@Valid @RequestBody IsoMessageRequest request){var canonical=mapper.toCanonical(request);var score=platform.score(authorization,canonical);return mapper.response(request,score);}
 @PostMapping("/events/evaluate")public GatewayDecisionResponse evaluateEvent(@RequestHeader(HttpHeaders.AUTHORIZATION)String authorization,@Valid @RequestBody CanonicalEventRequest request){return evaluation.evaluate(authorization,request);}
 @PostMapping("/lab/scenarios:run")public LabScenarioResponse runLab(@RequestHeader(HttpHeaders.AUTHORIZATION)String authorization,@Valid @RequestBody LabScenarioRequest request){return lab.run(authorization,request);}}
